import type { WorkGroup } from './work-group-model';
import type { WorkLocation } from './work-location-model';

export const ApplicationUserRoleKeyToLabel = {
  'Administrator': 'Administrator',
  'SafetyOfficerSpecialist': 'Safety Officer Specialist',
  'SPOC': 'SPOC',
  'Supervisor': 'Supervisor',
  'Auditor': 'Auditor'
} as const;
export type ApplicationUserRoleKey = keyof typeof ApplicationUserRoleKeyToLabel;

export interface ApplicationUser {
  /**
   * @displayName Application User ID
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName Application User Name
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  applicationUserName: string;
  /**
   * @displayName Active
   * @validationRule Required for create/update operations
   */
  active: boolean;
  /**
   * @displayName Email
   * @validationRule Required for create/update operations
   */
  email: string;
  /**
   * @displayName Manager
   */
  manager?: Pick<ApplicationUser, 'id' | 'applicationUserName'>;
  /**
   * @displayName Phone
   */
  phone?: string;
  /**
   * @displayName Role
   * @validationRule Required for create/update operations
   */
  roleKey: ApplicationUserRoleKey;
  /**
   * @displayName Work Group
   * @validationRule Required for create/update operations
   */
  workGroup: Pick<WorkGroup, 'id' | 'workGroupName'>;
  /**
   * @displayName Work Location
   * @validationRule Required for create/update operations
   */
  workLocation: Pick<WorkLocation, 'id' | 'workLocationName'>;
}

export const _ApplicationUser = 'ApplicationUser' as const;